(function () {
  var TS = window.TripsStore;
  var CAROUSEL_H = 500;
  var AUTOPLAY_MS = 5000;
  var FALLBACK_IMG = 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=1000&q=80';
  var carouselTimers = {};
  var modalCarouselTimer = null;

  var IMG_WA = 'data:image/png;base64,';
  var IMG_FB = 'data:image/png;base64,';
  var IMG_TT = 'data:image/png;base64,';

  function escapeHtml(s) {
    return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  }

  function socialButtonsHtml(trip, size) {
    var s = TS.getSiteSettings();
    var isLg = size === 'lg';
    var base = isLg
      ? 'flex-1 flex items-center justify-center gap-2 py-4 rounded-2xl font-bold text-sm transition-all hover:scale-105'
      : 'flex items-center justify-center p-3 rounded-2xl transition-all hover:scale-105';
    var waPhone = (s.whatsappPhone || trip.whatsappPhone || '18290000000').replace(/\D/g,'');
    var waHref  = 'https://wa.me/' + waPhone + '?text=' + encodeURIComponent('Info: ' + trip.title);
    var iSz     = isLg ? 'w-7 h-7' : 'w-6 h-6';
    var btns = '';
    btns += '<a href="' + escapeHtml(waHref) + '" target="_blank" rel="noopener noreferrer"'
          + ' class="' + base + ' bg-[#25D366] hover:bg-[#1eba58] shadow-md pulse-ws" aria-label="WhatsApp"'
          + ' onclick="event.stopPropagation()">'
          + '<img src="' + IMG_WA + '" class="' + iSz + ' object-contain" alt="WhatsApp">'
          + (isLg ? '<span class="text-white font-bold">WhatsApp</span>' : '')
          + '</a>';
    if (s.facebookUrl) {
      btns += '<a href="' + escapeHtml(s.facebookUrl) + '" target="_blank" rel="noopener noreferrer"'
            + ' class="' + base + ' bg-[#1877F2] hover:bg-[#0d65da] shadow-md" aria-label="Facebook"'
            + ' onclick="event.stopPropagation()">'
            + '<img src="' + IMG_FB + '" class="' + iSz + ' object-contain" alt="Facebook">'
            + (isLg ? '<span class="text-white font-bold">Facebook</span>' : '')
            + '</a>';
    }
    if (s.tiktokUrl) {
      btns += '<a href="' + escapeHtml(s.tiktokUrl) + '" target="_blank" rel="noopener noreferrer"'
            + ' class="' + base + ' bg-black hover:bg-zinc-800 shadow-md" aria-label="TikTok"'
            + ' onclick="event.stopPropagation()">'
            + '<img src="' + IMG_TT + '" class="' + iSz + ' object-contain" alt="TikTok">'
            + (isLg ? '<span class="text-white font-bold">TikTok</span>' : '')
            + '</a>';
    }
    return btns;
  }

  function priceBlock(t) {
    if (t.hidePrice) return '';
    var disc = Number(t.discountPercent) || 0;
    var fin  = TS.formatMoney(TS.finalPrice(t));
    var orig = TS.formatMoney(t.price);
    if (disc > 0) {
      return '<div class="text-right leading-tight font-black">'
           + '<div class="text-xs text-black/70 line-through">RD$ ' + escapeHtml(orig) + '</div>'
           + '<div class="text-xl">RD$ ' + escapeHtml(fin) + '</div>'
           + '<div class="text-[10px] font-bold text-black/60 uppercase tracking-wider">-' + escapeHtml(String(disc)) + '%</div>'
           + '</div>';
    }
    return '<span class="font-black text-lg">RD$ ' + escapeHtml(fin) + '</span>';
  }

  function cardHtml(t, index) {
    var delay = (index * 0.1).toFixed(1);
    var imgs  = TS.tripImagesList(t);
    if (!imgs.length) imgs = [FALLBACK_IMG];
    var cid  = escapeHtml(t.id);
    var desc = t.description
      ? '<p class="text-sm text-white/70 line-clamp-3 mb-4 leading-relaxed">' + escapeHtml(t.description) + '</p>'
      : '';
    var slides = imgs.map(function(src,i) {
      return '<div class="h-full shrink-0 snap-center snap-always" style="flex:0 0 100%">'
           + '<img src="' + escapeHtml(src) + '" class="w-full h-full object-cover object-center transition-transform duration-700 group-hover:scale-105" alt="' + escapeHtml(t.title) + ' ' + (i+1) + '" loading="lazy">'
           + '</div>';
    }).join('');
    var dots = imgs.map(function(_,i) {
      return '<button type="button" class="sa-dot h-2 rounded-full transition-all bg-white/30 w-2 hover:bg-white/60" data-i="' + i + '" aria-label="Foto ' + (i+1) + '"></button>';
    }).join('');
    var arrows = imgs.length > 1
      ? '<button type="button" class="sa-prev absolute left-3 top-1/2 -translate-y-1/2 z-20 w-11 h-11 rounded-full bg-black/50 hover:bg-black/70 text-white text-xl flex items-center justify-center" aria-label="Ant">&#8249;</button>'
      + '<button type="button" class="sa-next absolute right-3 top-1/2 -translate-y-1/2 z-20 w-11 h-11 rounded-full bg-black/50 hover:bg-black/70 text-white text-xl flex items-center justify-center" aria-label="Sig">&#8250;</button>'
      + '<div class="sa-dots absolute bottom-28 left-0 right-0 flex justify-center gap-2 z-20">' + dots + '</div>'
      : '';

    return '<div class="sa-card fade-in-up relative group rounded-[3rem] overflow-hidden bg-zinc-900 shadow-3xl cursor-pointer transition-all duration-500 hover:-translate-y-4 hover:shadow-[0_30px_60px_-15px_rgba(0,0,0,0.5)]"'
         + ' style="animation-delay:' + delay + 's;">'
         + '<div class="relative" style="height:' + CAROUSEL_H + 'px">'
         + '<div class="sa-carousel flex h-full overflow-x-auto overflow-y-hidden snap-x snap-mandatory scroll-smooth no-scrollbar" tabindex="0" style="scrollbar-width:none;-ms-overflow-style:none">'
         + slides + '</div>'
         + '<div class="absolute inset-0 bg-gradient-to-t from-[#070d1b] via-[#070d1b]/20 to-transparent pointer-events-none"></div>'
         + arrows
         + (t.hidePrice ? '' : '<div class="absolute top-8 right-8 bg-[#F5B800] text-black px-6 py-2.5 rounded-2xl shadow-xl z-20 pointer-events-none">' + priceBlock(t) + '</div>')
         + '<div class="absolute bottom-10 left-10 right-10 z-10 pointer-events-none">'
         + '<div class="pointer-events-auto">'
         + '<div class="flex flex-wrap items-center gap-3 text-xs font-bold uppercase tracking-widest mb-4">'
         + '<span class="text-[#F5B800]">\u{1F4CD} ' + escapeHtml(t.location || 'RD') + '</span>'
         + '<span class="bg-white/10 px-4 py-1.5 rounded-full backdrop-blur-md">\u{1F4C5} ' + escapeHtml(TS.formatDateBadge(t)) + '</span>'
         + '</div>'
         + '<h2 class="text-4xl md:text-5xl font-extrabold leading-tight mb-3">' + escapeHtml(t.title) + '</h2>'
         + desc
         + '<div class="flex gap-3 mt-2">'
         + '<a href="' + escapeHtml(t.formUrl) + '" target="_blank" rel="noopener noreferrer" onclick="event.stopPropagation()" class="flex-1 bg-white text-black font-black text-center py-5 rounded-2xl hover:bg-[#F5B800] transition-colors uppercase tracking-widest text-sm shadow-md">Anotarme</a>'
         + socialButtonsHtml(t,'sm')
         + '</div></div></div></div></div></div>';
  }

  /* ── Modal de asientos (solo lectura) ───────────────────────────── */
  function buildSeatModal() {
    if (document.getElementById('seat-modal')) return;
    var el = document.createElement('div');
    el.id = 'seat-modal';
    el.setAttribute('role','dialog');
    el.setAttribute('aria-modal','true');
    el.className = 'hidden fixed inset-0 z-[320] bg-black/95 backdrop-blur-sm flex items-center justify-center p-4';
    el.innerHTML =
      '<div class="w-full max-w-sm bg-gradient-to-br from-[#070d1b] to-[#0a1628] rounded-[1.75rem] overflow-hidden shadow-2xl border border-white/10 p-6 max-h-[92vh] overflow-y-auto">'
      + '<div class="flex items-start justify-between gap-4 mb-4">'
        + '<div>'
          + '<p class="text-[#F5B800] text-[11px] font-bold uppercase tracking-widest mb-1">Disponibilidad</p>'
          + '<h3 class="sa-seat-title text-lg font-extrabold text-white leading-tight"></h3>'
        + '</div>'
        + '<button type="button" class="sa-seat-close shrink-0 w-9 h-9 rounded-full bg-white/20 hover:bg-white/30 text-xl leading-none flex items-center justify-center text-white transition-colors" aria-label="Cerrar">×</button>'
      + '</div>'
      + '<div class="sa-seat-map mb-4"></div>'
      + '<div class="sa-seat-legend text-white/80"></div>'
      + '<p class="text-white/40 text-[11px] mt-4 leading-relaxed">Este mapa lo actualiza el equipo de Super Aventureros. Para reservar tu asiento, contáctanos por WhatsApp.</p>'
      + '</div>';
    document.body.appendChild(el);
    el.querySelector('.sa-seat-close').addEventListener('click', closeSeatModal);
    el.addEventListener('click', function (e) { if (e.target === el) closeSeatModal(); });
    document.addEventListener('keydown', function (e) {
      if (e.key === 'Escape' && !el.classList.contains('hidden')) closeSeatModal();
    });
  }

  function openSeatModal(trip) {
    buildSeatModal();
    var modal = document.getElementById('seat-modal');
    modal.querySelector('.sa-seat-title').textContent = trip.title || 'Mapa de asientos';
    var seatMap = TS.getBusSeatMap(trip);
    modal.querySelector('.sa-seat-map').innerHTML = TS.renderBusSeatMapHtml(seatMap, false);
    modal.querySelector('.sa-seat-legend').innerHTML = TS.renderBusSeatLegendHtml();
    modal.classList.remove('hidden');
    document.body.style.overflow = 'hidden';
  }

  function closeSeatModal() {
    var modal = document.getElementById('seat-modal');
    if (modal) modal.classList.add('hidden');
    if (!document.getElementById('product-modal') || document.getElementById('product-modal').classList.contains('hidden')) {
      document.body.style.overflow = '';
    }
  }

  /* ── Modal ───────────────────────────────────────────────────── */
  function buildModal() {
    if (document.getElementById('product-modal')) return;
    var el = document.createElement('div');
    el.id = 'product-modal';
    el.setAttribute('role','dialog');
    el.setAttribute('aria-modal','true');
    el.className = 'hidden fixed inset-0 z-[300] bg-black/95 backdrop-blur-sm flex items-end md:items-center justify-center p-4 md:p-6 overflow-hidden';
    el.innerHTML =
      '<div class="w-full max-w-6xl max-h-[98vh] md:max-h-[92vh] bg-gradient-to-br from-[#070d1b] to-[#0a1628] rounded-t-[2rem] md:rounded-[2rem] overflow-hidden flex flex-col md:flex-row shadow-2xl border border-white/10">'
      + '<div class="relative md:w-1/2 shrink-0 h-80 md:h-auto md:min-h-[580px] bg-black/40 overflow-hidden">'
        + '<button type="button" class="sa-modal-back absolute top-5 left-5 z-30 md:flex hidden items-center gap-2 px-4 py-2 rounded-full bg-black/70 hover:bg-black/90 text-white text-xs font-bold uppercase tracking-widest backdrop-blur-md transition-all">← Volver</button>'
        + '<div class="sa-carousel flex h-full overflow-x-auto overflow-y-hidden snap-x snap-mandatory scroll-smooth no-scrollbar"></div>'
        + '<div class="absolute inset-0 bg-gradient-to-t from-black/50 via-transparent to-transparent pointer-events-none"></div>'
        + '<button type="button" class="sa-modal-prev absolute left-3 top-1/2 -translate-y-1/2 z-10 w-12 h-12 rounded-full bg-black/60 hover:bg-black/80 text-white text-xl hidden md:flex items-center justify-center transition-all">‹</button>'
        + '<button type="button" class="sa-modal-next absolute right-3 top-1/2 -translate-y-1/2 z-10 w-12 h-12 rounded-full bg-black/60 hover:bg-black/80 text-white text-xl hidden md:flex items-center justify-center transition-all">›</button>'
        + '<div class="sa-dots absolute bottom-5 left-0 right-0 flex justify-center gap-2 z-10"></div>'
      + '</div>'
      + '<div class="flex-1 overflow-y-auto p-6 md:p-8 flex flex-col gap-6">'
        + '<div class="flex items-start justify-between gap-4">'
          + '<div class="flex-1">'
            + '<div class="flex flex-wrap items-center gap-3 mb-4">'
              + '<span class="sa-location text-[#F5B800] text-sm font-bold uppercase tracking-wider"></span>'
              + '<span class="sa-date bg-white/10 px-3 py-1 rounded-full backdrop-blur-md text-white text-xs font-semibold"></span>'
            + '</div>'
            + '<h2 class="sa-title text-3xl md:text-4xl font-extrabold leading-tight text-white" style="font-family:\'Playfair Display\',serif"></h2>'
          + '</div>'
          + '<button type="button" class="sa-modal-close shrink-0 w-10 h-10 rounded-full bg-white/20 hover:bg-white/30 text-2xl leading-none flex items-center justify-center text-white transition-colors" aria-label="Cerrar">×</button>'
        + '</div>'
        + '<div class="sa-price bg-gradient-to-r from-[#F5B800] to-[#FFD000] text-black self-start px-5 py-3 rounded-2xl shadow-lg font-black text-base"></div>'
        + '<p class="sa-description text-white/70 text-sm leading-relaxed flex-1"></p>'
        + '<div class="pt-2 flex flex-col gap-3">'
          + '<a class="sa-form-btn w-full bg-white text-black font-black text-center py-4 rounded-xl hover:bg-[#F5B800] transition-all duration-300 uppercase tracking-widest text-sm shadow-lg" href="#" target="_blank" rel="noopener noreferrer">Anotarme</a>'
          + '<button type="button" class="sa-seats-btn w-full bg-white/10 hover:bg-white/20 text-white font-bold text-center py-3 rounded-xl transition-all duration-300 uppercase tracking-widest text-xs flex items-center justify-center gap-2">🚌 Ver disponibilidad de asientos</button>'
          + '<div class="sa-social flex flex-wrap gap-2"></div>'
        + '</div>'
      + '</div>'
      + '</div>';
    document.body.appendChild(el);
    el.querySelector('.sa-modal-close').addEventListener('click', closeModal);
    el.querySelector('.sa-modal-back').addEventListener('click', closeModal);
    el.addEventListener('click', function(e) { if(e.target===el) closeModal(); });
    
    // Escape key support
    var escHandler = function(e) {
      if(e.key === 'Escape' && !document.getElementById('product-modal').classList.contains('hidden')) {
        closeModal();
      }
    };
    document.addEventListener('keydown', escHandler);
  }

  function openModal(trip) {
    buildModal();
    var modal = document.getElementById('product-modal');
    var imgs = TS.tripImagesList(trip);
    if (!imgs.length) imgs = [FALLBACK_IMG];
    var car  = modal.querySelector('.sa-carousel');
    car.innerHTML = imgs.map(function(src,i) {
      return '<div class="h-full w-full shrink-0 snap-center snap-always" style="flex:0 0 100%">'
           + '<img src="' + escapeHtml(src) + '" class="w-full h-full object-cover" alt="' + escapeHtml(trip.title) + ' ' + (i+1) + '" loading="eager">'
           + '</div>';
    }).join('');
    car.scrollTo({left:0,behavior:'auto'});

    var dotsEl  = modal.querySelector('.sa-dots');
    var prevBtn = modal.querySelector('.sa-modal-prev');
    var nextBtn = modal.querySelector('.sa-modal-next');
    if (imgs.length > 1) {
      prevBtn.classList.remove('hidden'); prevBtn.classList.add('flex');
      nextBtn.classList.remove('hidden'); nextBtn.classList.add('flex');
      dotsEl.innerHTML = imgs.map(function(_,i){
        return '<button type="button" class="h-2 rounded-full transition-all bg-white/30 w-2"></button>';
      }).join('');
      function slideW() { return car.clientWidth || 1; }
      function goPm(d)  { car.scrollBy({left:d*slideW(),behavior:'smooth'}); }
      function updDots() {
        var idx = Math.round(car.scrollLeft/slideW());
        dotsEl.querySelectorAll('button').forEach(function(d,i){
          if(i===idx){d.classList.add('bg-[#F5B800]','w-6');d.classList.remove('bg-white/30','w-2');}
          else{d.classList.remove('bg-[#F5B800]','w-6');d.classList.add('bg-white/30','w-2');}
        });
      }
      prevBtn.onclick = function(){ goPm(-1); };
      nextBtn.onclick = function(){ goPm(1);  };
      dotsEl.querySelectorAll('button').forEach(function(dot, dotIdx){
        dot.addEventListener('click',function(){
          car.scrollTo({left:dotIdx*slideW(),behavior:'smooth'});
        });
      });
      car.addEventListener('scroll',updDots,{passive:true});
      updDots();
      if(modalCarouselTimer) clearInterval(modalCarouselTimer);
      modalCarouselTimer = setInterval(function(){
        if(document.hidden) return;
        var maxS = car.scrollWidth - car.clientWidth;
        if(car.scrollLeft >= maxS-4) car.scrollTo({left:0,behavior:'smooth'}); else goPm(1);
      }, AUTOPLAY_MS);
    } else {
      prevBtn.classList.add('hidden'); nextBtn.classList.add('hidden'); dotsEl.innerHTML='';
    }

    modal.querySelector('.sa-location').textContent = '📍 ' + (trip.location || 'RD');
    modal.querySelector('.sa-date').textContent = '📅 ' + TS.formatDateBadge(trip);
    modal.querySelector('.sa-title').textContent = trip.title;
    modal.querySelector('.sa-description').textContent = trip.description || '';

    var priceEl = modal.querySelector('.sa-price');
    if (trip.hidePrice) {
      priceEl.innerHTML = '';
      priceEl.style.display = 'none';
    } else {
      priceEl.style.display = '';
      var disc = Number(trip.discountPercent)||0;
      var fin  = TS.formatMoney(TS.finalPrice(trip));
      var orig = TS.formatMoney(trip.price);
      priceEl.innerHTML = disc > 0
        ? '<span class="line-through text-black/60 text-sm mr-2">RD$ '+escapeHtml(orig)+'</span>RD$ '+escapeHtml(fin)+' <span class="text-xs ml-1 bg-black/20 rounded px-2 py-0.5">-'+escapeHtml(String(disc))+'%</span>'
        : 'RD$ '+escapeHtml(fin);
    }

    modal.querySelector('.sa-form-btn').href = trip.formUrl || '#';
    modal.querySelector('.sa-social').innerHTML = socialButtonsHtml(trip,'lg');
    var seatsBtn = modal.querySelector('.sa-seats-btn');
    if (seatsBtn) seatsBtn.onclick = function (e) { e.stopPropagation(); openSeatModal(trip); };

    modal.classList.remove('hidden');
    document.body.style.overflow = 'hidden';
  }

  function closeModal() {
    var modal = document.getElementById('product-modal');
    if(modal) modal.classList.add('hidden');
    if(modalCarouselTimer){ clearInterval(modalCarouselTimer); modalCarouselTimer=null; }
    document.body.style.overflow = '';
  }

  /* ── Boton flotante WhatsApp ─────────────────────────────────── */
  function updateWaFloat() {
    var el = document.getElementById('wa-float');
    if (!el) return;
    var s = TS.getSiteSettings();
    var phone = (s.whatsappPhone || '').replace(/\D/g, '');
    if (phone) {
      el.href = 'https://wa.me/' + phone;
    }
  }

  /* ── Banner ──────────────────────────────────────────────────── */
  function renderBanner() {
    var el = document.getElementById('site-banner');
    if(!el) return;
    var s = TS.getSiteSettings();
    if(!s.bannerEnabled || !String(s.bannerText||'').trim()){
      el.classList.add('hidden'); el.innerHTML=''; el.setAttribute('aria-hidden','true'); return;
    }
    el.classList.remove('hidden'); el.setAttribute('aria-hidden','false');
    el.innerHTML='<div class="max-w-5xl mx-auto px-4 py-3 text-center text-sm md:text-base font-semibold text-[#070d1b]">'+escapeHtml(s.bannerText).replace(/\n/g,'<br>')+'</div>';
  }

  /* ── Card carousels ──────────────────────────────────────────── */
  function clearCarouselTimers(){
    Object.keys(carouselTimers).forEach(function(k){ clearInterval(carouselTimers[k]); delete carouselTimers[k]; });
  }

  function wireCarousels() {
    clearCarouselTimers();
    var trips = TS.getTripsSorted();
    var cards = document.querySelectorAll('.sa-card');
    cards.forEach(function(card, cardIdx){
      var trip = trips[cardIdx];
      card.addEventListener('click', function(e){
        if(e.target.closest('a')||e.target.closest('.sa-prev')||e.target.closest('.sa-next')||e.target.closest('.sa-dot')) return;
        if(trip) openModal(trip);
      });
    });
    var carousels = document.querySelectorAll('.sa-carousel');
    carousels.forEach(function(sc, scIdx){
      var trip = trips[scIdx]; if(!trip) return;
      function slideW(){ return sc.clientWidth||1; }
      function go(d){ sc.scrollBy({left:d*slideW(),behavior:'smooth'}); }
      function updDots(){
        var idx = Math.round(sc.scrollLeft/slideW());
        var card = sc.closest('.sa-card'); if(!card) return;
        card.querySelectorAll('.sa-dot').forEach(function(d,i){
          if(i===idx){d.classList.add('bg-[#F5B800]','w-6');d.classList.remove('bg-white/30','w-2');}
          else{d.classList.remove('bg-[#F5B800]','w-6');d.classList.add('bg-white/30','w-2');}
        });
      }
      var wrap=sc.closest('.relative');
      if(wrap){
        var prev=wrap.querySelector('.sa-prev'), next=wrap.querySelector('.sa-next');
        if(prev) prev.addEventListener('click',function(e){e.stopPropagation();go(-1);});
        if(next) next.addEventListener('click',function(e){e.stopPropagation();go(1);});
      }
      sc.querySelectorAll('.sa-dot').forEach(function(dot, dotIdx){
        dot.addEventListener('click',function(e){e.stopPropagation();sc.scrollTo({left:dotIdx*slideW(),behavior:'smooth'});});
      });
      sc.addEventListener('scroll',updDots,{passive:true});
      updDots();
      if(sc.children.length>1){
        var timerId = 'carousel_'+scIdx;
        carouselTimers[timerId]=setInterval(function(){
          if(document.hidden)return;
          var maxS=sc.scrollWidth-sc.clientWidth;
          if(sc.scrollLeft>=maxS-4)sc.scrollTo({left:0,behavior:'smooth'});else go(1);
        },AUTOPLAY_MS);
      }
    });
  }

  function render(){
    var grid=document.getElementById('catalog-grid'); 
    if(!grid) return;
    try {
      var trips=TS.getTripsSorted();
      if(!trips.length){
        grid.innerHTML='<div class="col-span-2 text-center py-24 text-white/30"><p class="text-2xl font-bold mb-2">Sin salidas disponibles</p><p class="text-sm">Próximamente nuevas aventuras. ¡Vuelve pronto!</p></div>';
        return;
      }
      var htmlParts = [];
      for(var i=0;i<trips.length;i++){
        try {
          var card = cardHtml(trips[i], i);
          if(card) htmlParts.push(card);
        } catch(e) {
          console.error('[cardHtml] Error rendering card:', trips[i], e);
        }
      }
      grid.innerHTML = htmlParts.join('');
    } catch(e) {
      console.error('[render] Fatal error:', e);
      grid.innerHTML = '<p style="color:rgba(255,255,255,.5);text-align:center;padding:2rem;">Error loading trips.</p>';
    }
    if(window.lucide&&lucide.createIcons) lucide.createIcons();
    wireCarousels();
  }

  function init(){
    buildModal();
    renderBanner();
    updateWaFloat();
    
    // Event listeners
    window.addEventListener('storage',function(e){
      if(e.key===TS.STORAGE_KEY) render();
      if(e.key===TS.SITE_KEY)    renderBanner();
    });
    window.addEventListener('sa-trips-updated',render);
    window.addEventListener('sa-site-updated', function() { renderBanner(); updateWaFloat(); });
    document.addEventListener('keydown',function(e){if(e.key==='Escape')closeModal();});
    
    // Cargar datos locales primero (sin esperar a Firebase)
    TS.initIfEmpty().then(function(){
      render();
      renderBanner();
      updateWaFloat();
    });
    
    // Firebase en background (no bloquea)
    if(typeof TripsFirebase !== 'undefined' && TripsFirebase.init){
      TripsFirebase.init().catch(function(e){
        console.error('[Catalog.init] Firebase', e);
      });
    }
  }

  window.Catalog={render:render,init:init,renderBanner:renderBanner,updateWaFloat:updateWaFloat};
})();